 useEffect(()=>{if(!teams.some(team=>team.id===selectedId))setSelectedId(teams[0]?.id||'')},[teams,selectedId]);
 const selected=teams.find(team=>team.id===selectedId);
 const deleteTeam=async(team:Team)=>{if(!confirm(`Delete team ${team.name}? Its roster will be removed. Existing matches will retain the team name.`))return;await api(`/teams/${team.id}`,{method:'DELETE'});await reload()};
 const deletePlayer=async(player:Player)=>{if(!confirm(`Remove ${player.name} from the roster?`))return;await api(`/players/${player.id}`,{method:'DELETE'});await reload()};
 return <main className="library teamPage">
  <div className="libraryTop"><div><p className="eyebrow">{t('roster_mgmt')}</p><h1>{t('teams')}</h1><p>{t('admin_subtitle_teams')}</p></div><ImportLeague/><a className="ghost"href="/templates/team-roster-template.csv"download>{t('csv_template')}</a><input ref={csvInput}type="file"accept=".csv,text/csv"hidden onChange={async e=>{const file=e.target.files?.[0];e.target.value='';if(!file)return;setCsvBusy(true);setCsvResult('');setCsvError(false);try{const form=new FormData();form.append('file',file);const result=await api<any>('/teams/import-csv',{method:'POST',body:form});setCsvResult(t('csv_import_result',{teams:String(result.teams_created),players:String(result.players_created),skipped:String(result.players_skipped)}));await reload()}catch(error){setCsvError(true);setCsvResult((error as Error).message)}finally{setCsvBusy(false)}}}/><button className="ghost"disabled={csvBusy}onClick={()=>csvInput.current?.click()}><Upload size={17}/> {csvBusy?t('csv_importing'):t('import_roster_csv')}</button><button className="primary"onClick={()=>setShowTeam(true)}><Plus size={18}/> {t('add_team')}</button></div>{csvResult&&<div className={csvError?'error':'notice'} role="status">{csvResult}</div>}
  {!teams.length?<div className="empty"><Users/><h2>{t('no_teams')}</h2><p>{t('team_identity')}</p><button className="primary"onClick={()=>setShowTeam(true)}>{t('create_team')}</button></div>:<div className="teamWorkspace">
   <aside className="teamList">{teams.map(team=><button key={team.id}className={selectedId===team.id?'active':''}onClick={()=>setSelectedId(team.id)}><TeamLogo team={team}/><span><b>{team.name}</b><small>{team.players.length} players · {team.season||'No season'}</small></span></button>)}</aside>
   {selected&&<section className="teamDetail"><div className="teamDetailHead"><div><TeamLogo team={selected} size="large"/><div><h2>{selected.name}</h2><p>{selected.season||'Season not set'}{selected.notes?` · ${selected.notes}`:''}</p></div></div><div className="actions"><input ref={logoInput}type="file"accept="image/png,image/jpeg,image/webp"hidden onChange={async e=>{const f=e.target.files?.[0];e.target.value='';if(!f)return;try{const fd=new FormData();fd.append('file',f);await api(`/teams/${selected.id}/logo`,{method:'POST',body:fd});await reload()}catch(x){setLogoError((x as Error).message)}}}/><button className="ghost"onClick={()=>logoInput.current?.click()}><ImagePlus size={16}/> {t('upload_logo')}</button>{selected.has_logo&&<button className="ghost"onClick={async()=>{try{await api(`/teams/${selected.id}/logo`,{method:'DELETE'});await reload()}catch(x){setLogoError((x as Error).message)}}}><X size={16}/> {t('remove_logo')}</button>}<button className="ghost"onClick={()=>setEditingTeam(selected)}><Pencil size={16}/> Edit</button><button className="ghost danger"onClick={()=>void deleteTeam(selected)}><Trash2 size={16}/> Delete</button></div></div>{logoError&&<div className="error clickable"onClick={()=>setLogoError('')}>{logoError}</div>}
    <div className="rosterHead"><div><h3>{t('roster')}</h3><p>{selected.players.length} {t('registered_players')}</p></div><button className="primary"onClick={()=>setShowPlayer(true)}><Plus size={16}/> {t('add_player')}</button></div>
    {!selected.players.length?<div className="empty compact"><p>{t('no_players')}</p></div>:<div className="playerTable"><div className="playerRow heading"><span>#</span><span>{t('player')}</span><span>{t('position')}</span><span>{t('status')}</span><span>{t('actions')}</span></div>{selected.players.map(player=><div className="playerRow"key={player.id}><b>{player.shirt_number||'–'}</b><span><strong>{player.name}</strong><small>{player.notes||t('no_notes')}</small></span><span>{player.position||'–'}</span><span className={player.active?'status active':'status'}>{player.active?t('active'):t('inactive')}</span><span className="rowActions"><button title={t('edit_player')}onClick={()=>setEditingPlayer(player)}><Pencil size={15}/></button><button className="danger"title={t('remove_player')}onClick={()=>void deletePlayer(player)}><Trash2 size={15}/></button></span></div>)}</div>}
   </section>}
  </div>}
  {showTeam&&<TeamModal close={()=>setShowTeam(false)}done={()=>{setShowTeam(false);void reload()}}/>}
  {editingTeam&&<TeamModal team={editingTeam}close={()=>setEditingTeam(undefined)}done={()=>{setEditingTeam(undefined);void reload()}}/>}
  {selected&&showPlayer&&<PlayerModal team={selected}close={()=>setShowPlayer(false)}done={()=>{setShowPlayer(false);void reload()}}/>}
  {selected&&editingPlayer&&<PlayerModal team={selected}player={editingPlayer}close={()=>setEditingPlayer(undefined)}done={()=>{setEditingPlayer(undefined);void reload()}}/>}
 </main>;
