function TeamModal({team,close,done}:{team?:Team;close:()=>void;done:()=>void}){
 const[name,setName]=useState(team?.name||'');
 const[season,setSeason]=useState(team?.season||'');
 const[notes,setNotes]=useState(team?.notes||'');
 const[players,setPlayers]=useState<DraftPlayer[]>([]);
 const[player,setPlayer]=useState<PlayerForm>({name:'',shirt_number:'',position:'CM'});
 const[error,setError]=useState(''),[saving,setSaving]=useState(false);
 const addPlayer=()=>{
  const playerName=player.name.trim();
  if(!playerName)return;
  setPlayers(current=>[...current,{name:playerName,shirt_number:player.shirt_number?Number(player.shirt_number):undefined,position:player.position}]);
  setPlayer({name:'',shirt_number:'',position:'CM'});
 };
 const submit=async(e:FormEvent<HTMLFormElement>)=>{
  e.preventDefault();
  if(saving)return;
  setSaving(true);setError('');
  try{
   let savedTeam:Team;
   if(team){
    savedTeam=await api<Team>(`/teams/${team.id}`,{method:'PUT',body:JSON.stringify({name,season:season||null,notes})});
   }else{
    savedTeam=await post('/teams',{name,season:season||null,notes}) as Team;
   }
   for(const draft of players)await post(`/teams/${savedTeam.id}/players`,{...draft,notes:'',active:true});
   done();
  }catch(reason){setError((reason as Error).message)}finally{setSaving(false)}
 };

 return <div className="modal"><form onSubmit={submit}>
  <h2>{team?t('edit_team'):t('create_team')}</h2><p className="muted">{t('team_identity')}</p>
  {error&&<div className="error"role="alert">{error}</div>}
  <label>{t('team_name')}<input required value={name}onChange={e=>setName(e.target.value)}/></label>
  <label>{t('season')}<input value={season}onChange={e=>setSeason(e.target.value)}placeholder="2026/27"/></label>
  <label>{t('notes')}<textarea value={notes}onChange={e=>setNotes(e.target.value)}placeholder="Club, age group, coach…"/></label>
  {!team&&<><h3>{t('initial_roster')} <small>{t('optional')}</small></h3><div className="rosterAdd">
   <input placeholder="Player name"value={player.name}onChange={e=>setPlayer(current=>({...current,name:e.target.value}))}/>
   <input type="number"min="1"max="99"placeholder="#"value={player.shirt_number}onChange={e=>setPlayer(current=>({...current,shirt_number:e.target.value}))}/>
   <select value={player.position}onChange={e=>setPlayer(current=>({...current,position:e.target.value}))}>{['GK','CB','FB','WB','DM','CM','AM','W','ST'].map(position=><option key={position}>{position}</option>)}</select>
   <button type="button"onClick={addPlayer}>{t('add')}</button>
  </div>
  <div className="rosterList">{players.map((draft,index)=><span key={`${draft.name}-${index}`}>#{draft.shirt_number||'–'} {draft.name} · {draft.position}<button type="button"onClick={()=>setPlayers(current=>current.filter((_,i)=>i!==index))}><X size={12}/></button></span>)}</div></>}
  <div className="actions"><button type="button"className="ghost"onClick={close}>{t('cancel')}</button><button type="submit"className="primary"disabled={saving}>{saving?t('saving'):t('save_team')}</button></div>
 </form></div>;
}

function PlayerModal({team,player,close,done}:{team:Team;player?:Player;close:()=>void;done:()=>void}){
 const[data,setData]=useState({name:player?.name||'',shirt_number:player?.shirt_number?.toString()||'',position:player?.position||'CM',notes:player?.notes||'',active:player?.active??true});
 const[error,setError]=useState(''),[saving,setSaving]=useState(false);
 const submit=async(e:FormEvent<HTMLFormElement>)=>{e.preventDefault();if(saving)return;setSaving(true);setError('');try{const payload={...data,shirt_number:data.shirt_number?Number(data.shirt_number):null};if(player)await api(`/players/${player.id}`,{method:'PUT',body:JSON.stringify(payload)});else await post(`/teams/${team.id}/players`,payload);done()}catch(reason){setError((reason as Error).message)}finally{setSaving(false)}};
 return <div className="modal"><form onSubmit={submit}><h2>{player?t('edit_player'):t('add_player')}</h2><p className="muted">{team.name} roster</p>{error&&<div className="error"role="alert">{error}</div>}<label>{t('name')}<input required value={data.name}onChange={e=>setData({...data,name:e.target.value})}/></label><div className="two"><label>{t('shirt_number')}<input type="number"min="1"max="99"value={data.shirt_number}onChange={e=>setData({...data,shirt_number:e.target.value})}/></label><label>{t('position')}<select value={data.position}onChange={e=>setData({...data,position:e.target.value})}>{['GK','CB','FB','WB','DM','CM','AM','W','ST'].map(position=><option key={position}>{position}</option>)}</select></label></div><label>{t('notes')}<textarea value={data.notes}onChange={e=>setData({...data,notes:e.target.value})}/></label><label className="check"><input type="checkbox"checked={data.active}onChange={e=>setData({...data,active:e.target.checked})}/> {t('active_player')}</label><div className="actions"><button type="button"className="ghost"onClick={close}>{t('cancel')}</button><button type="submit"className="primary"disabled={saving}>{saving?t('saving'):t('save_player')}</button></div></form></div>;
}
