function AnalysisHeader({match,back,addVideo,teams}:{match:Match;back:()=>void;addVideo:()=>void;teams:Team[]}){const byId=Object.fromEntries(teams.map(team=>[team.id,team]));return <header><button className="ghost"onClick={back}><ArrowLeft/></button><div className="brand"><span>M</span>Modulo a Farfalla</div><div className="matchTitle"><b className="matchNames">{match.home_team_id&&<TeamLogo team={byId[match.home_team_id]} size="mini"/>}{match.home_team} {t('vs')} {match.away_team}{match.away_team_id&&<TeamLogo team={byId[match.away_team_id]} size="mini"/>}</b><small>{match.competition} · {match.date}</small></div><button className="ghost"onClick={addVideo}><Upload size={17}/>{t('add_video')}</button><a className="ghost"href={`/api/matches/${match.id}/export.csv`}><Download size={17}/> CSV</a><a className="ghost"href={`/api/matches/${match.id}/export.json`}><Download size={17}/> JSON</a><ExportMatch match={match}/></header>}
const CATEGORY_COLORS:Record<string,string>={Goal:'#e11d48',Shot:'#f59e0b',Save:'#06b6d4',Pass:'#3b82f6',Cross:'#8b5cf6',Corner:'#d97706','Free Kick':'#16a34a',Tackle:'#ef4444',Foul:'#7f1d1d',Offside:'#64748b',Carry:'#0ea5e9',Note:'#94a3b8',Header:'#a16207'};
function Timeline({duration,events,current,seek,filter,setFilter}:{duration:number;events:Event[];current:number;seek:(n:number)=>void;filter:string;setFilter:(s:string)=>void}){const cats=[...new Set(events.map(e=>e.category.name))];const shown=events.filter(x=>!filter||x.category.name===filter);const lanes:number[]=new Array(shown.length).fill(0);const ends:number[]=[-1,-1,-1,-1];shown.map((e,i)=>{const left=e.timestamp/duration*100;let lane=0;for(let l=0;l<4;l++){if(left>=ends[l]){lane=l;break}}lanes[i]=lane;ends[lane]=left+Math.max(0.6,(e.end||e.timestamp+5)-(e.start||e.timestamp-5))/duration*100});return <div className="timelineBlock"><div className="timeline"onClick={e=>{const r=e.currentTarget.getBoundingClientRect();seek((e.clientX-r.left)/r.width*duration)}}><div className="progress"style={{width:`${current/duration*100}%`}}/>{shown.map((e,i)=><button key={e.id}className={`${e.ai?'ai':''} tsym`}style={{left:`${e.timestamp/duration*100}%`,top:`${4+lanes[i]*8}px`,height:`${26-lanes[i]*6}px`,width:`${Math.max(0.6,Math.min(6,(e.end||e.timestamp+5)-(e.start||e.timestamp-5))/duration*100)}%`,background: e.ai?'#8b5cf6':(CATEGORY_COLORS[e.category.name]||'#e9b829')}}onClick={x=>{x.stopPropagation();seek(e.timestamp)}}><span className="tlIcon">{e.ai?'✨':(CATEGORY_ICONS[e.category.name]||e.category.icon||'•')}</span><span className="tlPop">{CATEGORY_ICONS[e.category.name]||'•'} {e.category.name} · {formatTime(e.timestamp)}{e.start!=null&&e.end!=null?` · ${formatTime(e.start)}–${formatTime(e.end)}`:''}{e.players?.length?` · ${e.players[0].player.name}`:''}{e.team?` · ${e.team}`:''}</span></button> )}</div><div className="tlFilters">{cats.map(c=>{const on=filter===c;return <button key={c}className={on?'active':''}style={on?{borderColor:CATEGORY_COLORS[c]||'#999',color:CATEGORY_COLORS[c]||'#555'}:undefined}onClick={()=>setFilter(on?'':c)}>{CATEGORY_ICONS[c]||'•'} {c}</button>})}{filter&&<button onClick={()=>setFilter('')}>✕</button>}</div></div>}

function DraftEditor({draft,setDraft,teams,onCancel,onSave,time}:{draft:any;setDraft:(d:any)=>void;teams:Team[];onCancel:()=>void;onSave:()=>Promise<void>;time:string}){const allPlayers=teams.flatMap((t:Team)=>t.players.map(p=>({...p,team:t.name})));const set=(patch:any)=>setDraft({...draft,...patch});return <div className="draftCard"><div className="editorTitle"><h3>{CATEGORY_ICONS[draft.category.name]||draft.category.icon} {draft.category.name} · {time}</h3></div><label>{t('team')}<select value={draft.team_id||''}onChange={e=>set({team_id:e.target.value||null})}><option value="">{t('no_team')}</option>{teams.map((t:Team)=><option key={t.id}value={t.id}>{t.name}</option>)}</select></label><div className="two"><label>{t('actor')}<select value={draft.players?.find((x:any)=>x.role==='actor')?draft.players.find((x:any)=>x.role==='actor').player_id:''}onChange={e=>{const id=e.target.value;const next=(draft.players||[]).filter((x:any)=>x.role!=='actor');if(id)next.push({player_id:id,role:'actor'});set({players:next})}}><option value="">{t('unassigned')}</option>{allPlayers.map((p:any)=><option key={p.id}value={p.id}>{p.team} · #{p.shirt_number||'–'} {p.name}</option>)}</select></label><label>{t('receiver')}<select value={draft.players?.find((x:any)=>x.role==='receiver')?draft.players.find((x:any)=>x.role==='receiver').player_id:''}onChange={e=>{const id=e.target.value;const next=(draft.players||[]).filter((x:any)=>x.role!=='receiver');if(id)next.push({player_id:id,role:'receiver'});set({players:next})}}><option value="">{t('unassigned')}</option>{allPlayers.map((p:any)=><option key={p.id}value={p.id}>{p.team} · #{p.shirt_number||'–'} {p.name}</option>)}</select></label></div>{Object.entries(draft.category.metadata_schema||{}).map(([key,options]:any)=><label key={key}>{key.replaceAll('_',' ')}<select value={draft.metadata?.[key]||''}onChange={e=>set({metadata:{...draft.metadata,[key]:e.target.value}})}><option value="">{t('not_set')}</option>{options.map((x:string)=><option key={x}>{x}</option>)}</select></label>)}<label>{t('note')}<textarea value={draft.note||''}onChange={e=>set({note:e.target.value})}placeholder={t('what_happened')}/></label><label>{t('tags')}<input value={draft.tags?.join(', ')}onChange={e=>set({tags:e.target.value.split(',').map((x:string)=>x.trim()).filter(Boolean)})}placeholder={t('pressing')}/></label><Pitch value={draft.pitch_x==null?undefined:[draft.pitch_x,draft.pitch_y]}change={(x,y)=>set({pitch_x:x,pitch_y:y})}/><div className="actions"><button type="button"className="ghost"onClick={onCancel}>{t('cancel')}</button><button type="button"className="primary"onClick={()=>void onSave()}>{t('save_event')}</button></div></div>}

function EventPanel({drawingDirty,events,all,categories,selected,select,filter,setFilter,search,setSearch,teams,save,remove}:any){const[winError,setWinError]=useState('');const allPlayers=teams.flatMap((t:Team)=>t.players.map(p=>({...p,team:t.name})));const rolePlayer=(role:string)=>selected?.players?.find((x:any)=>x.role===role)?.player.id||'';const setWindowValue=(field:'start'|'end',raw:string,target:HTMLInputElement)=>{const value=parseTime(raw);const fallback=field==='start'?selected.start:selected.end;const other=field==='start'?selected.end:selected.start;const invalid=value==null||(other!=null&&(field==='start'?value>=other:value<=other));if(invalid){target.value=fallback!=null?formatTime(fallback):'';setWinError(t('window_invalid'));return}setWinError('');void save(selected,{[field]:value})};useEffect(()=>setWinError(''),[selected?.id]);const setRole=(role:string,playerId:string)=>{const next=(selected.players||[]).filter((x:any)=>x.role!==role).map((x:any)=>({player_id:x.player.id,role:x.role}));if(playerId)next.push({player_id:playerId,role});save(selected,{players:next})};const doSave=async()=>{if(!selected)return;await save(selected,{})};return <div className="eventPanel"><div className="filters"><select value={filter}onChange={e=>setFilter(e.target.value)}><option value="">{t('all_categories',{n:String(all.length)})}</option>{categories.map((c:Category)=><option value={c.id}key={c.id}>{c.name}</option>)}</select><div className="search small"><Search/><input value={search}onChange={e=>setSearch(e.target.value)}placeholder={t('search_notes')}/></div></div>{selected&&<div className="editor"><div className="editorTitle"><h3>{selected.category.name} · {formatTime(selected.timestamp)}</h3><div className="editorActions"><button onClick={()=>remove(selected)}title={t('delete')}><Trash2/></button></div></div><label>{t('team')}<select value={selected.team_id||''}onChange={e=>save(selected,{team_id:e.target.value||null})}><option value="">{t('no_team')}</option>{teams.map((t:Team)=><option key={t.id}value={t.id}>{t.name}</option>)}</select></label><div className="two"><label>{t('actor')}<select value={rolePlayer('actor')}onChange={e=>setRole('actor',e.target.value)}><option value="">{t('unassigned')}</option>{allPlayers.map((p:any)=><option key={p.id}value={p.id}>{p.team} · #{p.shirt_number||'–'} {p.name}</option>)}</select></label><label>{t('receiver')}<select value={rolePlayer('receiver')}onChange={e=>setRole('receiver',e.target.value)}><option value="">{t('unassigned')}</option>{allPlayers.map((p:any)=><option key={p.id}value={p.id}>{p.team} · #{p.shirt_number||'–'} {p.name}</option>)}</select></label></div>{Object.entries(selected.category.metadata_schema||{}).map(([key,options]:any)=><label key={key}>{key.replaceAll('_',' ')}<select value={selected.metadata?.[key]||''}onChange={e=>save(selected,{metadata:{...selected.metadata,[key]:e.target.value}})}><option value="">{t('not_set')}</option>{options.map((x:string)=><option key={x}>{x}</option>)}</select></label>)}<label>{t('note')}<textarea key={selected.id+'note'}defaultValue={selected.note}onBlur={e=>save(selected,{note:e.target.value})}placeholder={t('what_happened')}/></label><label>{t('tags')}<input defaultValue={selected.tags.join(', ')}onBlur={e=>save(selected,{tags:e.target.value.split(',').map(x=>x.trim()).filter(Boolean)})}placeholder={t('pressing')}/></label><Pitch value={selected.pitch_x==null?undefined:[selected.pitch_x,selected.pitch_y]}change={(x,y)=>save(selected,{pitch_x:x,pitch_y:y})}/><div className="two"><label>{t('window_from')}<input key={selected.id+'ws'}defaultValue={selected.start!=null?formatTime(selected.start):''}placeholder="45:30"inputMode="numeric"onBlur={e=>setWindowValue('start',e.target.value,e.target)}/></label><label>{t('window_to')}<input key={selected.id+'we'}defaultValue={selected.end!=null?formatTime(selected.end):''}placeholder="49:32"inputMode="numeric"onBlur={e=>setWindowValue('end',e.target.value,e.target)}/></label></div>{winError&&<p className="error"role="alert">{winError}</p>}<ClipExport key={selected.id} event={selected} hasUnsavedDrawings={drawingDirty}/></div>}<div className="eventList">{events.map((e:Event)=><button className={selected?.id===e.id?'selected':''}key={e.id}onClick={()=>select(e)}><span className="eventIcon">{e.category.icon}</span><span><b>{e.category.name}</b><small>{e.note||e.players?.map(x=>x.player.name).join(' → ')||e.team||t('no_details')}</small></span><time>{formatTime(e.timestamp)}</time></button>)}</div></div>}function Pitch({value,change}:{value?:number[];change:(x:number,y:number)=>void}){return <><label>{t('pitch_position')}</label><div className="pitch"onClick={e=>{const r=e.currentTarget.getBoundingClientRect();change((e.clientX-r.left)/r.width,(e.clientY-r.top)/r.height)}}><div className="half"/><div className="circle"/>{value&&<i style={{left:`${value[0]*100}%`,top:`${value[1]*100}%`}}/>}</div></>}

function Stats({matchId,events,seek}:{matchId:string;events:Event[];seek:(id:string)=>void}){const[stats,setStats]=useState<any[]>([]),[group,setGroup]=useState('overview');useEffect(()=>{api(`/matches/${matchId}/stats`).then(setStats)},[events.length]);const groups=[...new Set(stats.map(s=>s.group))] as string[];return <div className="stats"><h2>{t('coach_stats')}</h2><p>Manual and calculated metrics are labelled. Every number drills into video.</p><div className="statTabs">{groups.map(g=><button className={group===g?'active':''}onClick={()=>setGroup(g)}>{g}</button>)}</div><div className="statGrid">{stats.filter(s=>s.group===group).map(s=><button key={s.name}onClick={()=>s.event_ids[0]&&seek(s.event_ids[0])}><b>{s.value}{s.name.includes('%')&&'%'}</b><span>{s.name}</span><small>{s.source} · {s.event_ids.length} events</small></button>)}</div><h3>{t('event_map')}</h3><div className="pitch map">{events.filter(e=>e.pitch_x!=null).map(e=><i key={e.id}title={e.category.name}style={{left:`${e.pitch_x!*100}%`,top:`${e.pitch_y!*100}%`}}onClick={()=>seek(e.id)}/>)}</div></div>}
function PlaylistRunner({events,seek,close}:{events:Event[];seek:(n:number)=>void;close:()=>void}){const[index,setIndex]=useState(0);useEffect(()=>{if(events[index])seek(events[index].start??events[index].timestamp)},[index]);return <div className="playlistRunner"><b>Filtered playback {index+1}/{events.length}</b><span>{events[index]?.category.name}</span><button disabled={index===0}onClick={()=>setIndex(index-1)}>{t('previous')}</button><button disabled={index>=events.length-1}onClick={()=>setIndex(index+1)}>{t('next')}</button><button onClick={close}>{t('close')}</button></div>}

function Application(){const[user,setUser]=useState<any>(null),[loading,setLoading]=useState(true),[match,setMatch]=useState<Match>();useEffect(()=>{api('/auth/me').then(setUser).catch(()=>{}).finally(()=>setLoading(false))},[]);if(loading)return <div className="splash">Modulo a Farfalla</div>;if(!user)return <Login onLogin={()=>api('/auth/me').then(setUser)}/>;if(user.role==='player')return <PlayerView user={user}logout={()=>api('/auth/logout',{method:'POST'}).then(()=>setUser(null))}/>;if(user.role==='admin')return <AdminConsole user={user}logout={()=>api('/auth/logout',{method:'POST'}).then(()=>setUser(null))}open={()=>setMatch(undefined)}/>;if(match)return <Analysis initial={match}back={()=>setMatch(undefined)}/>;return <Library open={setMatch}logout={()=>api('/auth/logout',{method:'POST'}).then(()=>setUser(null))}/>}

export default function App(){return <><DesktopStatus/><Application/></>}
